// spec: .qa/e2e/specs/moderation-menu.md 1.1 · seed: tests/seed.user4.moderation.spec.ts · тикеты #714b7a (AC 4–5, реджект r8), #4d3a4c (AC 4, 6)
// @data: user4 создаёт пост «QA-AUTO …» и удаляет его (в finally — запасное удаление по id). Окно iPhone 13 Mini.
import { test, expect } from '@playwright/test';
import { postCard, openFeed } from '../post-create/post-helpers';
import { tapIn, appApi, closeApp, createPost, deletePost, iphoneAs, postVisibleToAuthor, qaText } from './mod-helpers';
import type { Api } from '../_shared/api';

test.describe('רכיב תפריט דיווח וחסימה — свой контент', () => {
  test('Свой пост: в меню «מחיקת הפוסט» без «דיווח»/«חסימת»; окно «למחוק את הפוסט?»; «ביטול» — пост остаётся, «מחיקה» — удалён @iphone @data (#714b7a #4d3a4c)', async ({ browser }) => {
    test.setTimeout(120_000);
    const page = await iphoneAs(browser, 'user4');
    const text = qaText('714b7a', 'own-post');
    let api: Api | undefined;
    let id = '';
    try {
      api = await appApi(page);
      id = await createPost(api, text);

      await openFeed(page);
      const card = postCard(page, text);
      await expect(card).toBeVisible();

      // Меню своего поста: удаление есть, жалобы и блокировки нет (AC 4; находка r8 — не мелькают «דיווח/חסימה»)
      await tapIn(page, card.getByRole('button', { name: 'פעולות על הפוסט' }));
      const menu = page.getByRole('dialog').filter({ hasText: 'פעולות על הפוסט' });
      await expect(menu.getByRole('button', { name: /מחיקת הפוסט/ })).toBeVisible();
      await expect(menu.getByRole('button', { name: /דיווח/ })).toHaveCount(0);
      await expect(menu.getByRole('button', { name: /חסימ/ })).toHaveCount(0);

      // Окно подтверждения (Confirm sheet 888:29204): заголовок, подзаголовок, «מחיקה» / «ביטול»
      await tapIn(page, menu.getByRole('button', { name: /מחיקת הפוסט/ }));
      const confirm = page.getByRole('dialog').filter({ hasText: 'למחוק את הפוסט?' });
      await expect(confirm).toBeVisible();
      await expect(confirm).toContainText('אי אפשר לשחזר אחרי מחיקה');
      await expect(confirm.getByRole('button', { name: 'מחיקה', exact: true })).toBeVisible();

      // «ביטול»: окно закрылось, пост на месте, экран реагирует (меню открывается снова) — реджект r8
      await tapIn(page, confirm.getByRole('button', { name: 'ביטול', exact: true }));
      await expect(confirm).toHaveCount(0);
      await expect(page.getByText(text, { exact: true })).toBeVisible();
      expect(await postVisibleToAuthor(api, id), 'пост не удалён после «ביטול»').toBe(true);

      // «מחיקה»: DELETE 2xx, пост исчез из ленты
      await tapIn(page, card.getByRole('button', { name: 'פעולות על הפוסט' }));
      await tapIn(page, page.getByRole('button', { name: /מחיקת הפוסט/ }));
      const del = page.waitForResponse((r) => r.request().method() === 'DELETE' && r.url().includes(`/rest/v1/posts?id=eq.${id}`));
      await tapIn(page, page.getByRole('dialog').filter({ hasText: 'למחוק את הפוסט?' }).getByRole('button', { name: 'מחיקה', exact: true }));
      expect((await del).ok(), 'DELETE /rest/v1/posts').toBeTruthy();
      await expect(page.getByText(text, { exact: true })).toHaveCount(0);
      expect(await postVisibleToAuthor(api, id)).toBe(false);
      id = '';
    } finally {
      if (api && id) await deletePost(api, id);
      await closeApp(page, 'user4');
    }
  });
});
